// Package strip removes swag annotations and generated spec files from a
// working copy, so each run regenerates them from scratch and re-runs are
// idempotent.
package strip

import (
	"bytes"
	"fmt"
	"go/scanner"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// SpecDir is where swag writes the generated spec, relative to the repo root.
const SpecDir = "internal/apispec"

// generated lists the files swag writes into SpecDir. docs.go is removed only
// when it carries swag's "Code generated" header, so a hand-written file of
// that name survives.
var generated = []string{"swagger.json", "swagger.yaml", "docs.go"}

// Result says what Run removed.
type Result struct {
	Files   int      `json:"files"`   // .go files that lost lines
	Lines   int      `json:"lines"`   // annotation lines removed
	Deleted []string `json:"deleted"` // generated spec files deleted, slash paths
}

// Run strips annotation lines from every .go file under dir (except .git)
// and deletes the generated files in SpecDir.
func Run(dir string) (Result, error) {
	res := Result{Deleted: []string{}}
	err := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		src, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out, n, err := Lines(filepath.Base(path), src)
		if err != nil || n == 0 {
			return err
		}
		res.Files++
		res.Lines += n
		return os.WriteFile(path, out, 0o644)
	})
	if err != nil {
		return res, err
	}
	for _, name := range generated {
		path := filepath.Join(dir, filepath.FromSlash(SpecDir), name)
		data, err := os.ReadFile(path)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return res, err
		}
		if name == "docs.go" && !bytes.Contains(data, []byte("Code generated by swaggo/swag")) {
			continue
		}
		if err := os.Remove(path); err != nil {
			return res, err
		}
		res.Deleted = append(res.Deleted, SpecDir+"/"+name)
	}
	// Leave no empty directory behind; Remove fails harmlessly if files remain.
	_ = os.Remove(filepath.Join(dir, filepath.FromSlash(SpecDir)))
	return res, nil
}

// IsAnnotation reports whether a line comment's text is a swag annotation:
// "// @…" or "//@…".
func IsAnnotation(comment string) bool {
	return strings.HasPrefix(comment, "// @") || strings.HasPrefix(comment, "//@")
}

// Lines returns src without its annotation lines, and how many it removed.
// An annotation line holds only a "// @" line comment and whitespace; a
// trailing comment after code is kept, and text inside string literals or
// block comments is never touched because the source is tokenized, not
// matched line by line.
func Lines(name string, src []byte) ([]byte, int, error) {
	fset := token.NewFileSet()
	file := fset.AddFile(name, -1, len(src))
	var errs scanner.ErrorList
	var s scanner.Scanner
	s.Init(file, src, func(pos token.Position, msg string) { errs.Add(pos, msg) }, scanner.ScanComments)

	var out bytes.Buffer
	last, n := 0, 0 // src[last:] is not yet copied
	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		if tok != token.COMMENT || !IsAnnotation(lit) {
			continue
		}
		off := file.Offset(pos)
		start := bytes.LastIndexByte(src[:off], '\n') + 1
		if len(bytes.TrimSpace(src[start:off])) > 0 {
			continue // code before the comment on the same line
		}
		end := len(src)
		if i := bytes.IndexByte(src[off:], '\n'); i >= 0 {
			end = off + i + 1
		}
		out.Write(src[last:start])
		last = end
		n++
	}
	if errs.Len() > 0 {
		return nil, 0, fmt.Errorf("scan %s: %w", name, errs.Err())
	}
	out.Write(src[last:])
	return out.Bytes(), n, nil
}
